package com.nevgiu.hrai.chat;

/**
 * Application-owned result of the candidate-discovery phase.
 *
 * <p>The top-level workflow fields preserve the original discovery contract. {@code candidateScope} is populated only
 * when Java observed successful tenant-authorized searches for every extracted reference. Its candidate cards are
 * copied from those exact tool results; they are never generated by the model. Refusal and clarification responses
 * intentionally return a {@code null} scope so clients fail closed instead of performing a second interpretation.</p>
 */
public record CvChatToolDiscoveryResponse(CvChatToolOrchestrationOutcome.Kind kind, String message,
                                          CvChatLanguageScopeResponse candidateScope) {

    static CvChatToolDiscoveryResponse from(CvChatToolOrchestrationOutcome outcome,
                                            CvChatLanguageScopeResponse candidateScope) {
        return new CvChatToolDiscoveryResponse(outcome.kind(), outcome.message(), candidateScope);
    }
}
